export function Avatar({ url }: { url: string }) {
  return (
    <View style={{ padding: 8 }}>
      <Image source={{ uri: url }} />
    </View>
  );
}

export function Terms() {
  return (
    <ScrollView style={{ padding: 16, alignItems: 'center' }}>
      <Text>Điều khoản 1</Text>
      <Text>Điều khoản 2</Text>
      <Text>Điều khoản 3</Text>
    </ScrollView>
  );
}

export function OrdersScreen() {
  const [orders, setOrders] = useState<Order[]>([]);

  useEffect(() => {
    api.getOrders().then(setOrders);
  }, []);

  return (
    <FlatList
      data={orders}
      keyExtractor={(o) => o.id}
      renderItem={({ item }) => <OrderRow order={item} />}
    />
  );
}

const linking = {
  prefixes: ['myapp://'],
  config: {
    screens: {
      Home: '',
      User: 'user/:id',
    },
  },
};

<NavigationContainer linking={linking}>
  <RootStack />
</NavigationContainer>

export function Counter() {
  const [count, setCount] = useState(0);

  const onPress = () => {
    setCount(count + 1);
    setCount(count + 1);
    setCount(count + 1);
  };

  return (
    <Pressable onPress={onPress}>
      <Text>{count}</Text>
    </Pressable>
  );
}

export function Cart() {
  const [items, setItems] = useState(['a']);

  const addItem = () => {
    items.push('b');
    setItems(items);
  };

  return (
    <Pressable onPress={addItem}>
      <Text>Items: {items.length}</Text>
    </Pressable>
  );
}

export function Timer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setSeconds(seconds + 1);
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return <Text>Seconds: {seconds}</Text>;
}

export function CartBadge() {
  const { name, count } = useSelector((state: RootState) => ({
    name: state.user.name,
    count: state.cart.items.length,
  }));

  return (
    <Text>
      {name}: {count}
    </Text>
  );
}

type Product = { id: string; title: string };

export function ProductList({ data }: { data: Product[] }) {
  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id}
      renderItem={(item) => <Text>{item.title}</Text>}
    />
  );
}

export function TaskList({ tasks, onDelete }: Props) {
  return (
    <FlatList
      data={tasks}
      keyExtractor={(item, index) => String(index)}
      renderItem={({ item }) => (
        <TaskRow task={item} onDelete={() => onDelete(item.id)} />
      )}
    />
  );
}

function TaskRow({ task, onDelete }: RowProps) {
  const [done, setDone] = useState(false);
  return (
    <View>
      <Text>{task.title}</Text>
      <Switch value={done} onValueChange={setDone} />
      <Button title="Xoá" onPress={onDelete} />
    </View>
  );
}

export function CityPicker({ cities }: { cities: City[] }) {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const renderItem = useCallback(({ item }: { item: City }) => (
    <Pressable onPress={() => setSelectedId(item.id)}>
      <Text style={{ color: item.id === selectedId ? 'tomato' : 'black' }}>
        {item.name}
      </Text>
    </Pressable>
  ), []);

  return (
    <FlatList
      data={cities}
      keyExtractor={(c) => c.id}
      renderItem={renderItem}
    />
  );
}

