async function openCamera() {
  try {
    const result = await PermissionsAndroid.request(
      PermissionsAndroid.PERMISSIONS.CAMERA,
    );
    if (result) {
      navigation.navigate('Camera');
    }
  } catch (e) {
    Alert.alert('Không có quyền camera');
  }
}

