      timeout: 1000,
    });
    console.log('done', res.status);
  } catch (e) {
    console.log('timeout');
  }
}

load();

let shown = '';

const search = (q, ms) =>
  new Promise((resolve) => setTimeout(() => resolve(q), ms));

async function onChange(q, ms) {
  const result = await search(q, ms);
  shown = result;
}

onChange('re', 300);
onChange('rea', 100);

setTimeout(() => console.log(shown), 500);

console.log('A');

setTimeout(() => console.log('B'), 0);

Promise.resolve().then(() => console.log('C'));

queueMicrotask(() => console.log('D'));

console.log('E');

export function ProgressBar() {
  const width = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.timing(width, {
      toValue: 300,
      duration: 500,
      useNativeDriver: true,
    }).start();
  }, [width]);

  return (
    <Animated.View style={{ height: 8, width, backgroundColor: 'green' }} />
  );
}

